import{_ as l,c as i,ag as e,o as t}from"./chunks/framework.BxW8Wou5.js";const c=JSON.parse('{"title":"3、TCP、UDP","description":"","frontmatter":{},"headers":[],"relativePath":"ruankao/软件设计师/第13章 - 计算机网络/3.TCP、UDP.md","filePath":"ruankao/软件设计师/第13章 - 计算机网络/3.TCP、UDP.md","lastUpdated":1762439185000}'),r={name:"ruankao/软件设计师/第13章 - 计算机网络/3.TCP、UDP.md"};function o(P,a,n,d,s,u){return t(),i("div",null,a[0]||(a[0]=[e('<h1 id="_3、tcp、udp" tabindex="-1">3、TCP、UDP <a class="header-anchor" href="#_3、tcp、udp" aria-label="Permalink to &quot;3、TCP、UDP&quot;">​</a></h1><h2 id="网际层-网络层-协议-ip" tabindex="-1">网际层（网络层）协议 - IP <a class="header-anchor" href="#网际层-网络层-协议-ip" aria-label="Permalink to &quot;网际层（网络层）协议 - IP&quot;">​</a></h2><ul><li>IP 所提供的服务是无连接、不可靠的</li><li>在网络性能良好的情况下，IP 传送的数据能够完好无损的到达目的地</li><li>所谓的无连接是指不管接收方是否已做好接收数据的准备之前就发送数据</li><li>至于不可靠的连接，是指目的系统不对成功接收的分组进行确认</li><li>因为无连接、不可靠，所以要将差错检测、流量控制、拥塞控制服务授权给其他各层协议</li></ul><h2 id="tcp-传输层" tabindex="-1">TCP（传输层） <a class="header-anchor" href="#tcp-传输层" aria-label="Permalink to &quot;TCP（传输层）&quot;">​</a></h2><ul><li>面向连接，可靠的</li><li>在 IP 提供的不可靠数据服务上为应用程序提供了一个可靠的、面向连接的全双工数据服务</li><li>三次握手</li><li>连接管理、差错校验和重传、流量控制、拥塞控制、端口寻址</li><li>流量控制采用的是：可变大小的滑动窗口协议</li><li>TCP/IP 和 ISO/OSI 中建立连接是在传输层，OSI/RM 中建立连接在会话层</li></ul><h2 id="udp-传输层" tabindex="-1">UDP（传输层） <a class="header-anchor" href="#udp-传输层" aria-label="Permalink to &quot;UDP（传输层）&quot;">​</a></h2><ul><li>无连接的、不可靠的</li><li>错误检测功能弱于 TCP</li><li>有助于提高传输速率</li><li>拥有端口寻址功能</li></ul>',7)]))}const h=l(r,[["render",o]]);export{c as __pageData,h as default};
